// link test - works with both bare and node
const drive_link = require('./')

const { encode, decode } = drive_link()
// real link from an autodrive: autobase key + hash of its signed core at length 2
const key = 'ob9bumuacys6sryiuxecnxxa9y7drtrth6bhrhgw8wgimh7ks3xo'
const hash = 'd14aaec6e6ea375079019a2f55f72f2e43f472724394310296fe97a727f26e1a'
const link = `dat://2.0.${key}.${hash}/main.js?ask=no#name=foo`
let failed = 0

check('decodes a full link', same(decode(link), { key: ['2', '0', key, hash], path: '/main.js', env: { ask: 'no' }, arg: { name: 'foo' } }))
check('encodes it back to the same link', encode(decode(link)) === link)
check('keeps a fork of 0', encode({ key: [2, 0, key, hash] }) === `dat://2.0.${key}.${hash}`)
check('adds the missing slash to a path', encode({ key: [2, 0, key, hash], path: 'main.js' }) === `dat://2.0.${key}.${hash}/main.js`)
check('short links work', same(decode(`dat://${key}`).key, ['', '', key, '']) && same(decode(`dat://3.${key}`).key, ['', '3', key, '']) && same(decode(`dat://2.0.${key}`).key, ['2', '0', key, '']))
const weird = { key: ['2', '0', key, hash], path: '/my files/ü?#%.js', env: { a: '1 2', b: '&' }, arg: { c: '#' } }
check('weird paths and params come back the same', same(decode(encode(weird)), weird))
check('refuses other protocols', throws(() => decode(`https://${key}`)))
check('refuses links it cant read back', throws(() => decode(`dat://1.2.3.${key}.${hash}`)) && throws(() => decode(`dat://2..${key}`)) && throws(() => encode({ key: [2, '', key, hash] })) && throws(() => encode({ key: ['', '', key, hash] })) && throws(() => encode({ key: [2, 0, '', ''] })))

console.log(failed ? `${failed} failed` : 'all good')
if (failed) throw new Error('drive-link tests failed')

/***************************************
HELPERS
***************************************/
function check (name, ok) {
  console.log(`${ok ? 'ok' : 'not ok'} ${name}`)
  if (!ok) failed++
}

function same (a, b) { return JSON.stringify(a) === JSON.stringify(b) }

function throws (fn) {
  try { fn() } catch { return true }
  return false
}
